<script lang="ts">
 import {untrack} from 'svelte';import {changeScore,type Team} from './logic';import CopyButton from '../../components/CopyButton.svelte';import type {ToolState} from '../../types';
 let {state:data=$bindable()}: {state:ToolState} = $props();untrack(()=>{data.teams??=[{name:'チーム A',score:0},{name:'チーム B',score:0}];data.history??=[];data.error??='';});let board:HTMLDivElement;
 function snapshot(){data.history=[...data.history,data.teams.map((t:Team)=>({...t}))].slice(-100);}
 function change(index:number,delta:number){try{const next=changeScore(data.teams,index,delta);snapshot();data.teams=next;data.error='';}catch(e){data.error=(e as Error).message;}}
 function count(amount:number){snapshot();data.teams=Array.from({length:amount},(_,i)=>data.teams[i]||{name:`チーム ${String.fromCharCode(65+i)}`,score:0});}
 function rename(index:number,event:Event){const name=(event.currentTarget as HTMLInputElement).value;snapshot();data.teams=data.teams.map((t:Team,i:number)=>({...t,name:i===index?name:t.name}));}
 async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(board.requestFullscreen)await board.requestFullscreen();else throw new Error('このブラウザでは全画面表示できません。');}catch(e){data.error=(e as Error).message;}}
</script>
<div class="action-row"><label>チーム数<select value={data.teams.length} onchange={e=>count(Number(e.currentTarget.value))}><option value="2">2チーム</option><option value="3">3チーム</option><option value="4">4チーム</option></select></label><button disabled={!data.history.length} onclick={()=>{data.teams=data.history[data.history.length-1];data.history=data.history.slice(0,-1);}}>Undo</button><button onclick={()=>{if(confirm('全チームの得点を0にしますか？')){snapshot();data.teams=data.teams.map((t:Team)=>({...t,score:0}));}}}>得点をリセット</button><button onclick={fullscreen}>全画面表示 / 解除</button></div>
{#if data.error}<p role="alert" class="error">{data.error}</p>{/if}
<div class="scoreboard" bind:this={board}>{#each data.teams as team,i}<section class="score-team"><label><span class="sr-only">チーム{i+1}の名前</span><input value={team.name} maxlength="40" onchange={e=>rename(i,e)}/></label><output aria-label={`${team.name}の得点`}>{team.score}</output><div class="action-row"><button onclick={()=>change(i,-1)} aria-label={`${team.name}を1点減らす`}>−1</button><button class="primary" onclick={()=>change(i,1)} aria-label={`${team.name}を1点加える`}>＋1</button><button onclick={()=>change(i,3)} aria-label={`${team.name}を3点加える`}>＋3</button></div></section>{/each}</div>
<div class="action-row"><CopyButton text={(data.teams as Team[]).map(t=>`${t.name}: ${t.score}`).join('\n')} label="得点をコピー"/></div><p class="tool-note">2〜4チーム、負の得点も使用可能。変更履歴は直近100操作まで。チーム数・名前変更・リセットもUndoできます。減らしたチームの情報はUndo以外では戻りません。全画面はEscapeで解除。ページ再読み込みで消去します。</p>
